-- ----------------------------
-- Table structure for hrm_attendance_group
-- ----------------------------
DROP TABLE IF EXISTS `hrm_attendance_group`;
CREATE TABLE `hrm_attendance_group`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '考勤组编号',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '名称',
  `dept_ids` varchar(4000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '适用部门编号数组',
  `employee_ids` varchar(4000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '适用员工编号数组',
  `open_wifi_card` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否开启 WiFi 打卡',
  `open_point_card` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否开启定位打卡',
  `shifts` json NOT NULL COMMENT '班次配置',
  `rest` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否法定节假日休息',
  `special_dates` json NOT NULL COMMENT '特殊日期配置',
  `points` json NOT NULL COMMENT '打卡地点配置',
  `wifis` json NOT NULL COMMENT 'WiFi 打卡配置',
  `deduct_rule` json NOT NULL COMMENT '扣款规则',
  `default_status` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否默认考勤组',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9002 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'HRM 考勤组表';

-- ----------------------------
-- Records of hrm_attendance_group
-- ----------------------------
