-- ----------------------------
-- Table structure for hrm_attendance_leave
-- ----------------------------
DROP TABLE IF EXISTS `hrm_attendance_leave`;
CREATE TABLE `hrm_attendance_leave`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '请假记录编号',
  `employee_id` bigint NOT NULL COMMENT '员工编号',
  `type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '请假类型',
  `start_time` datetime NULL DEFAULT NULL COMMENT '请假开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '请假结束时间',
  `day` decimal(10, 2) NULL DEFAULT NULL COMMENT '请假时长',
  `reason` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '请假理由',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `approval_status` tinyint NULL DEFAULT NULL COMMENT '审批状态：1 审批中，2 通过，3 拒绝，4 取消；NULL 为历史已生效记录',
  `process_instance_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'BPM 流程实例编号',
  `approval_time` datetime NULL DEFAULT NULL COMMENT '审批完成时间',
  `approval_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审批或取消原因',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_hrm_attendance_leave_process_instance_id`(`process_instance_id` ASC) USING BTREE,
  INDEX `idx_hrm_attendance_leave_employee_id`(`employee_id` ASC) USING BTREE,
  INDEX `idx_hrm_attendance_leave_approval_status`(`approval_status` ASC) USING BTREE,
  INDEX `idx_hrm_att_leave_employee_status_time`(`employee_id` ASC, `approval_status` ASC, `start_time` ASC, `end_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'HRM 员工请假记录表';

-- ----------------------------
-- Records of hrm_attendance_leave
-- ----------------------------
