-- ----------------------------
-- Table structure for hrm_employee
-- ----------------------------
DROP TABLE IF EXISTS `hrm_employee`;
CREATE TABLE `hrm_employee`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '员工编号',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '员工姓名',
  `job_number` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工号',
  `user_id` bigint NULL DEFAULT NULL COMMENT '系统用户编号',
  `mobile` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '手机号',
  `country` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '国家地区',
  `nation` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '民族',
  `id_type` tinyint NULL DEFAULT NULL COMMENT '证件类型：1 身份证，2 港澳通行证，3 台湾通行证，4 护照，5 其他',
  `id_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '证件号码',
  `sex` tinyint NULL DEFAULT NULL COMMENT '性别，字典 system_user_sex',
  `email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '邮箱',
  `native_place` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '籍贯',
  `birthday` datetime NULL DEFAULT NULL COMMENT '出生日期',
  `age` int NULL DEFAULT NULL COMMENT '年龄',
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '户籍地址',
  `highest_education` tinyint NULL DEFAULT NULL COMMENT '最高学历',
  `dept_id` bigint NULL DEFAULT NULL COMMENT '部门编号',
  `leader_employee_id` bigint NULL DEFAULT NULL COMMENT '直属上级员工编号',
  `entry_status` tinyint NULL DEFAULT NULL COMMENT '入职状态：1 在职，2 待入职，3 待离职，4 离职',
  `status` tinyint NULL DEFAULT NULL COMMENT '员工状态：1 正式，2 试用，3 实习，4 兼职，5 劳务，6 顾问，7 返聘，8 外包',
  `type` tinyint NULL DEFAULT NULL COMMENT '聘用形式：1 正式，2 非正式',
  `entry_time` datetime NULL DEFAULT NULL COMMENT '入职时间',
  `probation` int NULL DEFAULT NULL COMMENT '试用期，单位月；0 表示无试用期',
  `regular_time` datetime NULL DEFAULT NULL COMMENT '转正时间',
  `leave_time` datetime NULL DEFAULT NULL COMMENT '离职时间',
  `post_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '职位名称',
  `post_level` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '岗位职级',
  `work_city` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工作城市',
  `work_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工作地址',
  `work_detail_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工作详细地址',
  `channel_id` bigint NULL DEFAULT NULL COMMENT '招聘渠道编号',
  `company_age_start_time` datetime NULL DEFAULT NULL COMMENT '司龄开始时间',
  `company_age` int NULL DEFAULT NULL COMMENT '司龄，单位年',
  `candidate_id` bigint NULL DEFAULT NULL COMMENT '关联招聘候选人编号',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_hrm_employee_job_number`(`job_number` ASC) USING BTREE,
  INDEX `idx_hrm_employee_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_hrm_employee_mobile`(`mobile` ASC) USING BTREE,
  INDEX `idx_hrm_employee_dept_id`(`dept_id` ASC) USING BTREE,
  INDEX `idx_hrm_employee_candidate_id`(`candidate_id` ASC) USING BTREE,
  INDEX `idx_hrm_employee_leader_employee_id`(`leader_employee_id` ASC) USING BTREE,
  INDEX `idx_hrm_employee_status_entry_regular_time`(`status` ASC, `entry_status` ASC, `regular_time` ASC) USING BTREE,
  INDEX `idx_hrm_employee_entry_status_entry_time`(`entry_status` ASC, `entry_time` ASC) USING BTREE,
  INDEX `idx_hrm_employee_entry_status_leave_time`(`entry_status` ASC, `leave_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 74 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'HRM 员工档案表';

