-- ----------------------------
-- Table structure for hrm_employee_change_record
-- ----------------------------
DROP TABLE IF EXISTS `hrm_employee_change_record`;
CREATE TABLE `hrm_employee_change_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '异动记录编号',
  `employee_id` bigint NOT NULL COMMENT '员工编号',
  `type` tinyint NULL DEFAULT NULL COMMENT '变动类型',
  `reason` tinyint NULL DEFAULT NULL COMMENT '异动原因',
  `old_dept_id` bigint NULL DEFAULT NULL COMMENT '原部门编号',
  `new_dept_id` bigint NULL DEFAULT NULL COMMENT '新部门编号',
  `old_post_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '原岗位名称',
  `new_post_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '新岗位名称',
  `old_post_level` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '原职级',
  `new_post_level` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '新职级',
  `old_work_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '原工作地点',
  `new_work_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '新工作地点',
  `old_leader_employee_id` bigint NULL DEFAULT NULL COMMENT '原直属上级员工编号',
  `new_leader_employee_id` bigint NULL DEFAULT NULL COMMENT '新直属上级员工编号',
  `probation` int NULL DEFAULT NULL COMMENT '试用期',
  `effect_time` datetime NULL DEFAULT NULL COMMENT '生效时间',
  `applied_time` datetime NULL DEFAULT NULL COMMENT '实际生效时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
