  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_hrm_employee_contract_employee_id`(`employee_id` ASC) USING BTREE,
  INDEX `idx_hrm_employee_contract_status_end_time`(`status` ASC, `end_time` ASC, `employee_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'HRM 员工合同表';

