-- ----------------------------
-- Table structure for hrm_performance_assessment_template
-- ----------------------------
DROP TABLE IF EXISTS `hrm_performance_assessment_template`;
CREATE TABLE `hrm_performance_assessment_template`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `name` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板名称',
  `illustrate` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '模板说明',
  `score_calculation` tinyint NULL DEFAULT 1 COMMENT '计分方式：1 加权计算',
  `upper_limit_type` tinyint NULL DEFAULT 0 COMMENT '上限类型：0 不限制，1 固定分',
  `upper_limit_score` decimal(10, 2) NULL DEFAULT 100.00 COMMENT '分数上限',
  `dimension_count` int NULL DEFAULT 0 COMMENT '维度数',
  `quota_count` int NULL DEFAULT 0 COMMENT '指标数',
  `dimensions` json NOT NULL COMMENT '考核维度配置',
  `status` tinyint NULL DEFAULT 0 COMMENT '状态，参见 common_status',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_hrm_performance_assessment_template_name`(`name` ASC) USING BTREE,
  INDEX `idx_hrm_perf_assessment_template_status_name`(`status` ASC, `name` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'HRM 绩效考核模板表';

-- ----------------------------
-- Records of hrm_performance_assessment_template
-- ----------------------------
