-- ----------------------------
-- Table structure for hrm_recruit_candidate
-- ----------------------------
DROP TABLE IF EXISTS `hrm_recruit_candidate`;
CREATE TABLE `hrm_recruit_candidate`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '候选人编号',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '候选人姓名',
  `mobile` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '手机',
  `sex` tinyint NOT NULL COMMENT '性别，字典 system_user_sex',
  `age` int NULL DEFAULT NULL COMMENT '年龄',
  `email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '邮箱',
  `post_id` bigint NULL DEFAULT NULL COMMENT '应聘职位编号',
  `stage_number` int NULL DEFAULT NULL COMMENT '面试轮次',
  `work_time` int NULL DEFAULT NULL COMMENT '工作年限',
  `education` tinyint NOT NULL COMMENT '学历：1 小学，2 初中，3 高中，4 大专，5 本科，6 硕士，7 博士',
  `graduate_school` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '毕业院校',
  `latest_work_place` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '最近工作单位',
  `channel_id` bigint NULL DEFAULT NULL COMMENT '招聘渠道编号',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `status` tinyint NULL DEFAULT NULL COMMENT '候选人状态：1 新候选人，2 初选通过，3 安排面试，4 面试通过，5 已发 offer，6 待入职，7 已淘汰，8 已入职，9 面试取消',
  `eliminate` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '淘汰原因',
  `status_update_time` datetime NULL DEFAULT NULL COMMENT '状态更新时间',
  `entry_time` datetime NULL DEFAULT NULL COMMENT '入职时间',
  `resume_urls` varchar(4000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '简历附件地址列表',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_hrm_recruit_candidate_name`(`name` ASC) USING BTREE,
  INDEX `idx_hrm_recruit_candidate_mobile`(`mobile` ASC) USING BTREE,
  INDEX `idx_hrm_recruit_candidate_post_id`(`post_id` ASC) USING BTREE,
  INDEX `idx_hrm_recruit_candidate_status`(`status` ASC) USING BTREE,
  INDEX `idx_hrm_recruit_candidate_status_update_time`(`status` ASC, `status_update_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 154 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'HRM 招聘候选人表';

-- ----------------------------
-- Records of hrm_recruit_candidate
