-- ----------------------------
-- Table structure for hrm_recruit_post
-- ----------------------------
DROP TABLE IF EXISTS `hrm_recruit_post`;
CREATE TABLE `hrm_recruit_post`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '招聘职位编号',
  `post_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '职位名称',
  `dept_id` bigint NULL DEFAULT NULL COMMENT '部门编号',
  `job_nature` tinyint NULL DEFAULT NULL COMMENT '工作性质：1 全职，2 实习，3 兼职',
  `area_id` int NULL DEFAULT NULL COMMENT '工作城市地区编号',
  `recruit_num` int NULL DEFAULT NULL COMMENT '招聘人数',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '招聘原因',
  `work_time` tinyint NULL DEFAULT NULL COMMENT '工作经验：1 不限，2 一年以内，3 一至三年，4 三至五年，5 五至十年，6 十年以上',
  `education_require` tinyint NULL DEFAULT NULL COMMENT '学历要求：1 不限，2 高中及以上，3 大专及以上，4 本科及以上，5 硕士及以上，6 博士',
  `min_salary` decimal(10, 2) NULL DEFAULT NULL COMMENT '最低薪资',
  `max_salary` decimal(10, 2) NULL DEFAULT NULL COMMENT '最高薪资',
  `salary_unit` tinyint NULL DEFAULT NULL COMMENT '薪资单位：1 元/年，2 元/月',
  `min_age` int NULL DEFAULT NULL COMMENT '最小年龄',
  `max_age` int NULL DEFAULT NULL COMMENT '最大年龄',
  `latest_entry_time` datetime NULL DEFAULT NULL COMMENT '最迟到岗时间',
  `owner_employee_id` bigint NULL DEFAULT NULL COMMENT '负责人员工编号',
  `interview_employee_ids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '面试官员工编号，逗号分隔',
  `description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '职位描述',
  `emergency_level` tinyint NULL DEFAULT NULL COMMENT '紧急程度：1 紧急，2 一般',
  `post_type_id` bigint NULL DEFAULT NULL COMMENT '职位类型编号',
  `status` tinyint NULL DEFAULT NULL COMMENT '职位状态：0 停止招聘，1 招聘中',
  `stop_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '停止原因',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_hrm_recruit_post_name`(`post_name` ASC) USING BTREE,
  INDEX `idx_hrm_recruit_post_dept_id`(`dept_id` ASC) USING BTREE,
  INDEX `idx_hrm_recruit_post_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'HRM 招聘职位表';

-- ----------------------------
-- Records of hrm_recruit_post
-- ----------------------------
