-- ----------------------------
-- Table structure for hrm_salary_change_record
-- ----------------------------
DROP TABLE IF EXISTS `hrm_salary_change_record`;
CREATE TABLE `hrm_salary_change_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `employee_id` bigint NOT NULL COMMENT '员工编号',
  `type` tinyint NULL DEFAULT NULL COMMENT '记录类型：1 定薪，2 调薪',
  `reason` tinyint NULL DEFAULT NULL COMMENT '原因',
  `effect_time` datetime NULL DEFAULT NULL COMMENT '生效时间',
  `before_total` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '调整前正式薪资',
  `after_total` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '调整后正式薪资',
  `probation_before_total` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '调整前试用期薪资',
  `probation_after_total` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '调整后试用期薪资',
  `salary_options` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '正式薪资项 JSON',
  `probation_salary_options` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '试用期薪资项 JSON',
  `status` tinyint NULL DEFAULT 1 COMMENT '状态',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_hrm_salary_change_record_employee_id`(`employee_id` ASC) USING BTREE,
  INDEX `idx_hrm_salary_change_status_effect_time`(`status` ASC, `effect_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'HRM 定薪/调薪记录表';

