-- ----------------------------
-- Table structure for hrm_salary_month_employee_record
-- ----------------------------
DROP TABLE IF EXISTS `hrm_salary_month_employee_record`;
CREATE TABLE `hrm_salary_month_employee_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `month_record_id` bigint NOT NULL COMMENT '月度工资表编号',
  `employee_id` bigint NOT NULL COMMENT '员工编号',
  `actual_work_day` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '实际工作天数',
  `need_work_day` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '应工作天数',
  `year` int NOT NULL COMMENT '年份',
  `month` int NOT NULL COMMENT '月份',
  `expected_pay_salary` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '应发工资',
  `taxable_salary` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '应税工资',
  `personal_tax` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '个人所得税',
  `real_pay_salary` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '实发工资',
  `option_values` json NULL COMMENT '薪资项值 JSON',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_hrm_salary_month_emp_record_record_id`(`month_record_id` ASC) USING BTREE,
  INDEX `idx_hrm_salary_month_emp_record_employee_id`(`employee_id` ASC) USING BTREE,
  INDEX `idx_hrm_salary_month_emp_record_month_employee`(`month_record_id` ASC, `employee_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 438 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'HRM 员工月度工资表';

