-- ----------------------------
-- Table structure for hrm_salary_month_record
-- ----------------------------
DROP TABLE IF EXISTS `hrm_salary_month_record`;
CREATE TABLE `hrm_salary_month_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `title` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工资表标题',
  `year` int NOT NULL COMMENT '年份',
  `month` int NOT NULL COMMENT '月份',
  `employee_count` int NULL DEFAULT 0 COMMENT '员工数',
  `start_time` datetime NULL DEFAULT NULL COMMENT '周期开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '周期结束时间',
  `expected_pay_salary` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '应发工资',
  `personal_tax` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '个人所得税',
  `real_pay_salary` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '实发工资',
  `personal_insurance_amount` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '个人社保',
  `personal_provident_fund_amount` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '个人公积金',
  `corporate_insurance_amount` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '公司社保',
  `corporate_provident_fund_amount` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '公司公积金',
  `option_headers` json NULL COMMENT '薪资项表头快照',
  `status` tinyint NULL DEFAULT 5 COMMENT '核算状态',
  `process_instance_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审批流程实例编号',
  `approval_status` tinyint NULL DEFAULT NULL COMMENT '审批状态',
  `approval_time` datetime NULL DEFAULT NULL COMMENT '审批完成时间',
  `approval_reason` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审批意见',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_hrm_salary_month_record_process_instance_id`(`process_instance_id` ASC) USING BTREE,
  INDEX `idx_hrm_salary_month_year_month_status`(`year` ASC, `month` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 29 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'HRM 月度工资表';

-- ----------------------------
-- Records of hrm_salary_month_record
