-- ----------------------------
-- Table structure for hrm_salary_option
-- ----------------------------
DROP TABLE IF EXISTS `hrm_salary_option`;
CREATE TABLE `hrm_salary_option`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `code` int NOT NULL COMMENT '薪资项编码',
  `parent_code` int NOT NULL DEFAULT 0 COMMENT '父级编码',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '薪资项名称',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `system_flag` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否系统默认项',
  `template_id` bigint NULL DEFAULT NULL COMMENT '标准薪资项目录编号',
  `type` tinyint NOT NULL DEFAULT 1 COMMENT '薪资项类型：0 减项，1 加项，2 计算项',
  `tax_enabled` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否计税',
  `visible` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否显示',
  `calculate_enabled` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否参与计算',
  `enabled` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否启用',
  `sort` int NULL DEFAULT NULL COMMENT '兼容旧运行包排序',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_hrm_salary_option_tenant_code`(`tenant_id` ASC, `code` ASC) USING BTREE,
  INDEX `idx_hrm_salary_option_parent_code`(`parent_code` ASC) USING BTREE,
  INDEX `idx_hrm_salary_option_template_id`(`template_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 139 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'HRM 薪资项表';

