-- ----------------------------
-- Table structure for hrm_salary_slip
-- ----------------------------
DROP TABLE IF EXISTS `hrm_salary_slip`;
CREATE TABLE `hrm_salary_slip`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `send_record_id` bigint NOT NULL COMMENT '工资条发放记录编号',
  `month_employee_record_id` bigint NOT NULL COMMENT '员工月度工资记录编号',
  `employee_id` bigint NOT NULL COMMENT '员工编号',
  `year` int NOT NULL COMMENT '年份',
  `month` int NOT NULL COMMENT '月份',
  `read_status` tinyint NULL DEFAULT 0 COMMENT '阅读状态',
  `real_pay_salary` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '实发工资',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `options` json NOT NULL COMMENT '工资条项',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_hrm_salary_slip_record_id`(`send_record_id` ASC) USING BTREE,
  INDEX `idx_hrm_salary_slip_employee_id`(`employee_id` ASC) USING BTREE,
  INDEX `idx_hrm_salary_slip_month_employee_record`(`month_employee_record_id` ASC) USING BTREE,
  INDEX `idx_hrm_salary_slip_employee_year_month`(`employee_id` ASC, `year` ASC, `month` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 45 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'HRM 工资条表';

-- ----------------------------
-- Records of hrm_salary_slip
