-- ----------------------------
-- Table structure for hrm_salary_slip_send_record
-- ----------------------------
DROP TABLE IF EXISTS `hrm_salary_slip_send_record`;
CREATE TABLE `hrm_salary_slip_send_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `month_record_id` bigint NOT NULL COMMENT '月度工资表编号',
  `employee_count` int NULL DEFAULT 0 COMMENT '工资表人数',
  `send_employee_count` int NULL DEFAULT 0 COMMENT '发放人数',
  `year` int NOT NULL COMMENT '年份',
  `month` int NOT NULL COMMENT '月份',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_hrm_salary_slip_record_salary_record_id`(`month_record_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'HRM 工资条发放记录表';

-- ----------------------------
-- Records of hrm_salary_slip_send_record
-- ----------------------------
BEGIN;
