-- ----------------------------
-- Table structure for hrm_salary_slip_template
-- ----------------------------
DROP TABLE IF EXISTS `hrm_salary_slip_template`;
CREATE TABLE `hrm_salary_slip_template`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板名称',
  `hide_empty` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否隐藏空项',
  `default_status` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否默认模板',
  `options` json NOT NULL COMMENT '工资条模板项',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'HRM 工资条模板表';

-- ----------------------------
-- Records of hrm_salary_slip_template
-- ----------------------------
BEGIN;
INSERT INTO `hrm_salary_slip_template` (`id`, `name`, `hide_empty`, `default_status`, `options`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`) VALUES (1, '默认工资条模板', b'0', b'1', '[{\"code\": 10101, \"name\": \"基本工资\", \"sort\": 10101, \"type\": 2, \"hidden\": 0, \"remark\": \"\", \"children\": []}, {\"code\": 10102, \"name\": \"岗位工资\", \"sort\": 10102, \"type\": 2, \"hidden\": 0, \"remark\": \"\", \"children\": []}, {\"code\": 210101, \"name\": \"应发工资\", \"sort\": 210101, \"type\": 2, \"hidden\": 0, \"remark\": \"\", \"children\": []}, {\"code\": 230101, \"name\": \"个人所得税\", \"sort\": 230101, \"type\": 2, \"hidden\": 0, \"remark\": \"\", \"children\": []}, {\"code\": 240101, \"name\": \"实发工资\", \"sort\": 240101, \"type\": 2, \"hidden\": 0, \"remark\": \"\", \"children\": []}]', 'admin', '2026-07-11 15:45:40', 'admin', '2026-07-27 08:53:19', b'0', 0), (2, '默认工资条模板', b'0', b'1', '[{\"code\": 10101, \"name\": \"基本工资\", \"sort\": 10101, \"type\": 2, \"hidden\": false, \"remark\": \"劳动合同中约定的标准工资。\", \"children\": []}, {\"code\": 10102, \"name\": \"岗位工资\", \"sort\": 10102, \"type\": 2, \"hidden\": false, \"remark\": \"根据岗位、责任、技能要求等，不同岗位，工资不同。\", \"children\": []}, {\"code\": 210101, \"name\": \"应发工资\", \"sort\": 210101, \"type\": 2, \"hidden\": false, \"remark\": \"应发工资=员工工资总额-请假扣款-考勤扣款等\", \"children\": []}, {\"code\": 230101, \"name\": \"个人所得税\", \"sort\": 230101, \"type\": 2, \"hidden\": false, \"remark\": \"根据个税计算规则，计算的每月应缴纳个税\", \"children\": []}, {\"code\": 240101, \"name\": \"实发工资\", \"sort\": 240101, \"type\": 2, \"hidden\": false, \"remark\": \"员工每月获得的实际收入。\", \"children\": []}]', '1', '2026-07-27 18:43:58', '1', '2026-07-27 18:43:58', b'0', 1), (3, 'UI自动化工资条模板-0730-编辑', b'0', b'0', '[{\"code\": 240, \"name\": \"实发工资\", \"sort\": 1, \"type\": 1, \"hidden\": false, \"remark\": null, \"children\": [{\"code\": 240101, \"name\": \"实发工资\", \"sort\": 2, \"type\": 2, \"hidden\": false, \"remark\": null, \"children\": []}]}, {\"code\": -1, \"name\": \"未分类科目\", \"sort\": 3, \"type\": 1, \"hidden\": false, \"remark\": null, \"children\": [{\"code\": 10101, \"name\": \"基本工资\", \"sort\": 4, \"type\": 2, \"hidden\": false, \"remark\": \"劳动合同中约定的标准工资。\", \"children\": []}, {\"code\": 10102, \"name\": \"岗位工资\", \"sort\": 5, \"type\": 2, \"hidden\": false, \"remark\": \"根据岗位、责任、技能要求等，不同岗位，工资不同。\", \"children\": []}, {\"code\": 10103, \"name\": \"职务工资\", \"sort\": 6, \"type\": 2, \"hidden\": false, \"remark\": \"根据职务高低、业务技术水平等因素的不同，工资不同，随职务变动而变动。\", \"children\": []}, {\"code\": 20101, \"name\": \"住房补贴\", \"sort\": 7, \"type\": 2, \"hidden\": false, \"remark\": \"为职工解决住房问题而给予的补贴资助。\", \"children\": []}, {\"code\": 20102, \"name\": \"高温津贴\", \"sort\": 8, \"type\": 2, \"hidden\": false, \"remark\": \"用人单位安排劳动者在高温天气下工作，当温度高于33℃，应支付高温补贴。\", \"children\": []}, {\"code\": 20103, \"name\": \"交通补贴\", \"sort\": 9, \"type\": 2, \"hidden\": false, \"remark\": \"企业按月按标准支付的交通补贴\", \"children\": []}, {\"code\": 20104, \"name\": \"餐补\", \"sort\": 10, \"type\": 2, \"hidden\": false, \"remark\": \"企业不统一供餐，而是按月按标准支付的午饭或晚餐补贴\", \"children\": []}, {\"code\": 30101, \"name\": \"绩效工资\", \"sort\": 11, \"type\": 2, \"hidden\": false, \"remark\": \"以员工的实际劳动成果或表现为考核标准，支付一定的奖励工资。\", \"children\": []}, {\"code\": 40101, \"name\": \"季度奖\", \"sort\": 12, \"type\": 2, \"hidden\": false, \"remark\": \"对于表现优秀的员工，按季度给予一定的奖励工资。\", \"children\": []}, {\"code\": 40102, \"name\": \"全勤奖\", \"sort\": 13, \"type\": 2, \"hidden\": false, \"remark\": \"对于按公司规定到岗工作，未出现任何迟到、早退的员工给予的奖励，一般以月度为考核期限。\", \"children\": []}, {\"code\": 40103, \"name\": \"推荐奖\", \"sort\": 14, \"type\": 2, \"hidden\": false, \"remark\": \"企业在招揽人才的过程中，对推荐人才并顺利入职的内部员工，给予的奖励工资。\", \"children\": []}, {\"code\": 50101, \"name\": \"销售提成\", \"sort\": 15, \"type\": 2, \"hidden\": false, \"remark\": \"对于销售或业务人员，通常按照一定的比例，企业和员工之间对盈利进行分成。\", \"children\": []}, {\"code\": 60101, \"name\": \"计件工资\", \"sort\": 16, \"type\": 2, \"hidden\": false, \"remark\": \"根据职工完成的劳动数量和按事先规定的计件单价计算和支付的工资。\", \"children\": []}, {\"code\": 70101, \"name\": \"计时工资\", \"sort\": 17, \"type\": 2, \"hidden\": false, \"remark\": \"根据职工的工作时间,按照工资标准、等级计算和支付的工资\", \"children\": []}, {\"code\": 80101, \"name\": \"工龄工资\", \"sort\": 18, \"type\": 2, \"hidden\": false, \"remark\": \"企业按照员工的工作年数，即员工的工作经验和劳动贡献的积累给予的经济补偿。\", \"children\": []}, {\"code\": 80102, \"name\": \"司龄工资\", \"sort\": 19, \"type\": 2, \"hidden\": false, \"remark\": \"司龄工资是按照劳动者在在公司做的时间的长短进行相应工资的计算。\", \"children\": []}, {\"code\": 90101, \"name\": \"职称工资\", \"sort\": 20, \"type\": 2, \"hidden\": false, \"remark\": \"工资高低与职称挂钩，职称越高，工资越高。\", \"children\": []}, {\"code\": 90102, \"name\": \"技能工资\", \"sort\": 21, \"type\": 2, \"hidden\": false, \"remark\": \"以员工个人所掌握的知识、技术和所具备的能力为基础来进行工资报酬的支付。\", \"children\": []}, {\"code\": 90103, \"name\": \"学历工资\", \"sort\": 22, \"type\": 2, \"hidden\": false, \"remark\": \"根据员工在教育机构取得的学历而给予适当的津贴。\", \"children\": []}]}]', '1', '2026-07-30 11:52:32', '1', '2026-07-30 11:53:26', b'1', 1), (4, '浏览器测试模板-1530-改', b'0', b'0', '[{\"code\": -2, \"name\": \"浏览器测试分类\", \"sort\": 1, \"type\": 1, \"hidden\": false, \"remark\": null, \"children\": [{\"code\": 10101, \"name\": \"基本工资\", \"sort\": 2, \"type\": 2, \"hidden\": true, \"remark\": null, \"children\": []}]}, {\"code\": 240, \"name\": \"实发工资\", \"sort\": 3, \"type\": 1, \"hidden\": false, \"remark\": null, \"children\": [{\"code\": 240101, \"name\": \"实发工资\", \"sort\": 4, \"type\": 2, \"hidden\": false, \"remark\": null, \"children\": []}]}, {\"code\": -1, \"name\": \"未分类科目\", \"sort\": 5, \"type\": 1, \"hidden\": false, \"remark\": null, \"children\": [{\"code\": 10102, \"name\": \"岗位工资\", \"sort\": 6, \"type\": 2, \"hidden\": false, \"remark\": \"根据岗位、责任、技能要求等，不同岗位，工资不同。\", \"children\": []}, {\"code\": 10103, \"name\": \"职务工资\", \"sort\": 7, \"type\": 2, \"hidden\": false, \"remark\": \"根据职务高低、业务技术水平等因素的不同，工资不同，随职务变动而变动。\", \"children\": []}, {\"code\": 20101, \"name\": \"住房补贴\", \"sort\": 8, \"type\": 2, \"hidden\": false, \"remark\