-- ----------------------------
-- Table structure for hrm_salary_tax_rule
-- ----------------------------
DROP TABLE IF EXISTS `hrm_salary_tax_rule`;
CREATE TABLE `hrm_salary_tax_rule`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '计税规则名称',
  `type` tinyint NULL DEFAULT NULL COMMENT '计税类型',
  `tax_enabled` bit(1) NULL DEFAULT NULL COMMENT '是否计税',
  `threshold` decimal(12, 2) NULL DEFAULT NULL COMMENT '起征阈值',
  `decimal_scale` int NULL DEFAULT NULL COMMENT '小数位数',
  `cycle_type` tinyint NULL DEFAULT NULL COMMENT '计税周期',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_hrm_salary_tax_rule_name`(`name` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'HRM 薪资计税规则表';

